import numpy as np
def pack(out):
    payoffs, basis = out
    return np.concatenate((np.asarray(payoffs, dtype=np.float64).ravel(), np.asarray(basis, dtype=np.float64).ravel()))
g = np.random.default_rng(5)
z = g.standard_normal((30, 4, 4))
dt = 1.0 / 4
paths = 90.0 * np.exp(np.concatenate((np.zeros((30, 1, 4)), np.cumsum((0.03 - 0.02 - 0.5 * 0.35 ** 2) * dt + 0.35 * np.sqrt(dt) * z, axis=1)), axis=1))
def permuted(fn):
    return pack(fn(paths[:, :, [2, 0, 3, 1]].copy(), 95.0, 1.0, 0.03, 0.02, 0.35))
assert np.allclose(permuted(build_max_call_payoffs_and_basis), target)

